// Generates src/permissions.generated.mjs from permissions.json.
//
//   node scripts/gen.mjs           write the generated file
//   node scripts/gen.mjs --check   exit 1 if the generated file is stale (CI)
//
// No dependencies: node's standard library only.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE = join(root, "permissions.json");
const TARGET = join(root, "src", "permissions.generated.mjs");
const KEY = /^[a-z]+(?:-[a-z]+)*:[a-z]+(?:-[a-z]+)*$/;

function load() {
  const { permissions } = JSON.parse(readFileSync(SOURCE, "utf8"));
  if (!Array.isArray(permissions)) throw new Error("permissions.json: `permissions` must be an array");
  const seen = new Set();
  for (const key of permissions) {
    if (typeof key !== "string" || !KEY.test(key)) throw new Error(`invalid permission key: ${JSON.stringify(key)}`);
    if (seen.has(key)) throw new Error(`duplicate permission key: ${key}`);
    seen.add(key);
  }
  return [...seen].sort();
}

const constName = (key) => key.replace(/[:-]/g, "_").toUpperCase();

function render(keys) {
  const byResource = new Map();
  for (const key of keys) {
    const [resource, action] = key.split(":");
    if (!byResource.has(resource)) byResource.set(resource, []);
    byResource.get(resource).push(action);
  }
  const lines = [
    "// @generated by scripts/gen.mjs from permissions.json. DO NOT EDIT BY HAND.",
    "// To change a permission, edit permissions.json and run `npm run gen`.",
    `// ${keys.length} permissions, ${byResource.size} resources.`,
    "",
    "export const PERMISSIONS = Object.freeze({",
    ...keys.map((k) => `  ${constName(k)}: ${JSON.stringify(k)},`),
    "});",
    "",
    "export const ALL_PERMISSIONS = Object.freeze([",
    ...keys.map((k) => `  PERMISSIONS.${constName(k)},`),
    "]);",
    "",
    "export const PERMISSIONS_BY_RESOURCE = Object.freeze({",
    ...[...byResource].map(([r, actions]) =>
      `  ${JSON.stringify(r)}: Object.freeze([${actions.map((a) => JSON.stringify(a)).join(", ")}]),`),
    "});",
    "",
  ];
  return lines.join("\n");
}

const out = render(load());
if (process.argv.includes("--check")) {
  let current = "";
  try { current = readFileSync(TARGET, "utf8"); } catch {}
  if (current !== out) {
    console.error("src/permissions.generated.mjs is stale: run `npm run gen`");
    process.exit(1);
  }
  console.log("src/permissions.generated.mjs is up to date");
} else {
  writeFileSync(TARGET, out);
  console.log(`wrote src/permissions.generated.mjs`);
}
